import type { GrammarNote, StoryChapter, StorySentence } from "../../types/story";
import { tokenize, type TokenSpec } from "../word-lexicon";

function makeSentence(
  id: string,
  tokens: TokenSpec[],
  pinyinText: string,
  translationPt: string,
  literalPt: string,
  grammarNotes?: GrammarNote[]
): StorySentence {
  const zhText = tokens.map((t) => (typeof t === "string" ? t : t.hanzi)).join("");
  return {
    id,
    zhText,
    pinyinText,
    translationPt,
    literalPt,
    ...(grammarNotes ? { grammarNotes } : {}),
    startMs: 0,
    endMs: 0,
    tokens: tokenize(id, tokens),
  };
}

